@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun CowsScreen(
 pastureId: Long? = null,
 onCowClick: (Long) -> Unit,
 onAddCowClick: () -> Unit
) {
 val context = LocalContext.current
 val database = CattleDatabase.getDatabase(context)
 val repository = CattleRepository(
