 colorMarkings = "Solid black",
 motherId = 4, // Will be set after insertion
 fatherId = 2, // Will be set after insertion
 pastureId = pastureIds[0], // North Field with mother
 status = Status.ACTIVE
 )
 )

 val cowIds = mutableListOf<Long>()
 cows.forEach { cow ->
 val id = insertCow(cow)
 cowIds.add(id)
 }

 // Update calf parent relationships with actual IDs
 if (cowIds.size >= 10) {
 val buddyId = cowIds[8] // Buddy
 val bellaId = cowIds[9] // Bella
 val bessieId = cowIds[2] // Bessie
 val daisyId = cowIds[3] // Daisy
 val thunderId = cowIds[0] // Thunder
 val stormId = cowIds[1] // Storm

 updateCow(getCowById(buddyId)!!.copy(motherId = bessieId, fatherId = thunderId))
 updateCow(getCowById(bellaId)!!.copy(motherId = daisyId, fatherId = stormId))
 }

 return cowIds
 }

