fun CattleNavigation(
 navController: NavHostController,
 modifier: Modifier = Modifier
) {
 NavHost(
 navController = navController,
 startDestination = Screen.Dashboard.route,
 modifier = modifier
 ) {
 composable("${Screen.Cows.route}?pastureId={pastureId}") { backStackEntry ->
 val pastureId = backStackEntry.arguments?.getString("pastureId")?.toLongOrNull()
 CowsScreen(
 pastureId = pastureId,
 onCowClick = { cowId ->
 navController.navigate("${Screen.CowInfo.route}/$cowId")
 },
 onCowEdit = { cowId ->
 navController.navigate("${Screen.CowDetail.route}/$cowId")
 },
 onAddCowClick = {
 navController.navigate("${Screen.CowDetail.route}/0")
 }
 )
 }

 composable(Screen.Cows.route) { 
 CowsScreen(
 pastureId = null, 
 onCowClick = { cowId ->
 navController.navigate("${Screen.CowInfo.route}/$cowId")
 },
 onCowEdit = { cowId ->
 navController.navigate("${Screen.CowDetail.route}/$cowId")
 },
 onAddCowClick = {
 navController.navigate("${Screen.CowDetail.route}/0") 
 }
 )
 }

 composable("${Screen.CowInfo.route}/{cowId}") { backStackEntry ->
 val cowId = backStackEntry.arguments?.getString("cowId")?.toLongOrNull() ?: 0L
 CowInfoScreen(
 cowId = cowId,
 onNavigateBack = { navController.popBackStack() },
 onEditCow = { navController.navigate("${Screen.CowDetail.route}/$cowId") }
 )
 }

 composable("${Screen.CowDetail.route}/{cowId}") { backStackEntry ->
 val cowId = backStackEntry.arguments?.getString("cowId")?.toLongOrNull() ?: 0L
 CowDetailScreen(
 cowId = cowId,
 onNavigateBack = { navController.popBackStack() }
 )
 }

 composable(Screen.Pastures.route) {
 PasturesScreen(
 onNavigateToAddPasture = {
 navController.navigate("${Screen.PastureDetail.route}/0") 
 },
 onNavigateToPastureDetails = { pastureId ->
 navController.navigate("${Screen.PastureDetail.route}/$pastureId")
 },
 onNavigateBack = { navController.popBackStack() }
 )
 }

 composable(Screen.Activities.route) {
 ActivitiesScreen(
 onAddActivityClick = {
 navController.navigate(Screen.AddActivity.route)
 },
 onEditActivityClick = { activity ->
 navController.navigate("${Screen.AddActivity.route}/${activity.id}")
 }
 )
 }

 composable(Screen.AddActivity.route) {
 AddActivityScreen(
 onNavigateBack = { navController.popBackStack() }
 )
 }

 composable("${Screen.AddActivity.route}/{activityId}") { backStackEntry ->
 val activityId = backStackEntry.arguments?.getString("activityId")?.toLongOrNull()
 AddActivityScreen(
 editId = activityId,
 onNavigateBack = { navController.popBackStack() }
 )
 }

 composable(Screen.Dashboard.route) {
 ReportsScreen(
 onShowList = { type, value ->
 if (type == "workingList") {
 navController.navigate(Screen.WorkingList.route)
 } else {
 val route = if (value != null) {
 "${Screen.CowList.route}?type=$type&value=$value"
 } else {
 "${Screen.CowList.route}?type=$type"
 }
 navController.navigate(route)
 }
 },
 onNavigateToAddBirth = { navController.navigate(Screen.AddBirth.route) } 
 )
 }

 composable(Screen.Notes.route) {
 NotesScreen(
 onNavigateBack = { navController.popBackStack() }
 )
 }

 composable("${Screen.CowList.route}?type={type}&value={value}") { backStackEntry ->
 val type = backStackEntry.arguments?.getString("type")
 val value = backStackEntry.arguments?.getString("value")
 CowListScreen(
 type = type,
 value = value,
 onCowClick = { cowId: Long -> navController.navigate("${Screen.CowInfo.route}/$cowId") },
 onBack = { navController.popBackStack() }
 )
 }

 composable(Screen.Settings.route) {
 SettingsScreen(
 onNavigateBack = { navController.popBackStack() }
 )
 }

 composable("${Screen.PastureDetail.route}/{pastureId}") { backStackEntry ->
 val pastureIdArg = backStackEntry.arguments?.getString("pastureId") ?: "0"

 val context = LocalContext.current
 val application = context.applicationContext as Application 
 val database = CattleDatabase.getDatabase(application) 
 val repository = remember {
 CattleRepository(
 cowDao = database.cowDao(),
 pastureDao = database.pastureDao(),
 activityDao = database.activityDao(),
 settingsDao = database.settingsDao(),
 noteDao = database.noteDao()
 )
 }
 val pasturesViewModel: PasturesViewModel = viewModel(
 factory = PasturesViewModelFactory(repository)
 )

 if (pastureIdArg == "0" || pastureIdArg.isEmpty()) { 
 AddPastureScreen(
 onAddPasture = { newPasture -> 
 pasturesViewModel.insertNewPasture(newPasture)
 navController.popBackStack()
 },
 onCancel = { navController.popBackStack() }
 )
 } else {
 PastureDetailScreen(
 pastureId = pastureIdArg,
 onNavigateBack = { navController.popBackStack() },
 onCowClick = { cowId ->
 navController.navigate("${Screen.CowInfo.route}/$cowId")
 },
 onCowEdit = { cowId ->
 navController.navigate("${Screen.CowDetail.route}/$cowId")
 },
 onEditPasture = {
 // TODO: Navigate to edit pasture screen when implemented
 // For now, this will be a no-op
 }
 )
 }
 }

 composable(Screen.AddBirth.route) { 
 AddBirthScreen(onNavigateBack = { navController.popBackStack() })
 }

 composable(Screen.WorkingList.route) {
 WorkingListScreen(onNavigateBack = { navController.popBackStack() })
 }
 }
}

sealed class Screen(val route: String, val title: String) {
 object Dashboard : Screen("dashboard", "Dashboard")
 object CowList : Screen("cow_list", "Cows")
 object Cows : Screen("cows", "Cows")
 object CowInfo : Screen("cow_info", "Cow Info")
 object CowDetail : Screen("cow_detail", "Cow Details")
 object Pastures : Screen("pastures", "Pastures")
 object PastureDetail : Screen("pasture_detail", "Pasture Details") 
 object Activities : Screen("activities", "Activities")
 object AddActivity : Screen("add_activity", "Add Activity")
 object Settings : Screen("settings", "Settings")
 object Notes : Screen("notes", "Notes")
 object AddBirth : Screen("add_birth", "Add Birth")
 object WorkingList : Screen("working_list", "Working List") 
}
","language":"kotlin"},"codebaseEnabled":true,"usedRules":["zen-rules://repo/.zencoder/rules/repo.md"]},"createdAt":1756860355367,"isInternal":false,"rawContent":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"I'd like to add login and sync. I've been told to keep using a room database and layer firestore. does that sound reasonable? Login would probably be via google social login? and i'd want multi user accounts so that I can share my herd with my partners"}]}]},"autoAppliedRules":[]},{"id":"09781f1e-0b9a-4a19-adb3-cfa7e21b3159","role":"assistant","content":[{"type":"text","text":"Yes, that sounds like a very reasonable architecture! Using Room as the local database with Firestore as the cloud backend is a common and effective pattern for Android apps, especially for agricultural/business applications where offline functionality is crucial. Here's why this approach works well for your cattle management app:

## Architecture Benefits

**Room + Firestore Layered Approach:**
- ✅ **Offline-first**: Critical for farm environments with poor connectivity
- ✅ **Fast UI**: Room provides instant local data access
- ✅ **Automatic sync**: Firestore handles real-time synchronization
- ✅ **Conflict resolution**: Firestore provides built-in conflict resolution
- ✅ **Scalable**: Can handle multiple users and large datasets

**Google Social Login:**
- ✅ **User-friendly**: Most people already have Google accounts
- ✅ **Secure**: Google handles authentication security
- ✅ **Easy integration**: Firebase Auth integrates seamlessly with Firestore

## Multi-User Sharing Strategy

For sharing herds with partners, you'll want to implement:

1. **Herd-based permissions** (not just user-based)
2. **Role-based access** (Owner, Manager, Viewer, etc.)
3. **Invitation system** for adding partners"},{"type":"toolCall","toolCallId":"toolu_01Qb19V5ZZUs9BQrwE4Tknwg","statusText":"Requirements collected","status":"SUCCESS","isHidden":false,"localResult":"{"answers":{"What level of access control do you need for partners?":"Simple read/write access for all partners","How do you want to handle data ownership and sync conflicts?":"Last write wins (simpler)","Do you want real-time collaboration features?":"Yes - see changes from partners immediately"}}"},{"type":"requirementsTool","id":"ec879af8-436b-46ff-bde6-099f63ec8e8c","questions":[{"question":"What level of access control do you need for partners?","options":["Simple read/write access for all partners","Role-based permissions (Owner, Manager, Viewer)","Granular permissions per feature (can edit cows, can view reports, etc.)","Just read-only access for partners"]},{"question":"How do you want to handle data ownership and sync conflicts?","options":["Last write wins (simpler)","Timestamp-based conflict resolution","Manual conflict resolution with user prompts","Field-level merging for different data types"]},{"question":"Do you want real-time collaboration features?","options":["Yes - see changes from partners immediately","Periodic sync (every few minutes/hours)","Manual sync only","Sync when app opens/closes"]}],"toolCallId":"toolu_01Qb19V5ZZUs9BQrwE4Tknwg","answers":{"What level of access control do you need for partners?":"Simple read/write access for all partners","How do you want to handle data ownership and sync conflicts?":"Last write wins (simpler)","Do you want real-time collaboration features?":"Yes - see changes from partners immediately"},"status":"SUCCESS"}],"context":{"author":"Code agent","operationId":"37c8220f-86cd-4f44-b6ef-b0526260c314"},"createdAt":1756860363619,"isInternal":false},{"id":"19750936-05f7-4e30-914c-b3cd195c3e61","role":"assistant","content":[{"type":"text","text":"Perfect! Based on your preferences, here's the implementation plan:

