+package com.jumblemint.cows.data.model
+
+import androidx.room.Entity
+import androidx.room.ForeignKey
+import androidx.room.Index
+import androidx.room.PrimaryKey
+
+@Entity(
+ tableName = "herd_members",
+ foreignKeys = [
+ ForeignKey(
+ entity = Herd::class,
+ parentColumns = ["id"],
+ childColumns = ["herdId"],
+ onDelete = ForeignKey.CASCADE
+ ),
+ ForeignKey(
+ entity = User::class,
+ parentColumns = ["uid"],
+ childColumns = ["userId"],
+ onDelete = ForeignKey.CASCADE
+ )
+ ],
+ indices = [
+ Index(value = ["herdId"]),
+ Index(value = ["userId"]),
+ Index(value = ["herdId", "userId"], unique = true)
+ ]
+)
+data class HerdMember(
+ @PrimaryKey(autoGenerate = true)
+ val id: Long = 0,
+ val herdId: String,
+ val userId: String,
+ val role: HerdRole = HerdRole.MEMBER,
+ val joinedAt: Long = System.currentTimeMillis(),
+ val invitedBy: String? = null,
+ val isActive: Boolean = true
+)
+
+enum class HerdRole {
+ OWNER, // Full access, can manage members
+ MEMBER // Read/write access to herd data
+}","refToolCallId":"toolu_01NCnXivCBFrpPJzWg8tAdgV"},{"type":"text","text":"Now I need to update the existing entities to include herd information and sync metadata:"},{"type":"toolCall","toolCallId":"toolu_01QJvfqw8maUEBuWxhBWDtV2","statusText":"Viewed file (lines 1:27)","status":"SUCCESS","context":{"files":[{"path":"app/src/main/java/com/jumblemint/cows/data/model/Cow.kt","fsPath":"C:/Users/jeepi/AndroidStudioProjects/cows/app/src/main/java/com/jumblemint/cows/data/model/Cow.kt"}]},"isHidden":false},{"type":"text","text":"I need to add herd and sync fields to the Cow entity:"},{"type":"toolCall","toolCallId":"toolu_01FyDuu6SGuauyNp1UCHfWnD","statusText":"Change generated","status":"SUCCESS","context":{"files":[{"path":"app/src/main/java/com/jumblemint/cows/data/model/Cow.kt","fsPath":"C:/Users/jeepi/AndroidStudioProjects/cows/app/src/main/java/com/jumblemint/cows/data/model/Cow.kt"}]},"isHidden":false},{"type":"codeHunk","lineBasedDiff":"--- C:/Users/jeepi/AndroidStudioProjects/cows/app/src/main/java/com/jumblemint/cows/data/model/Cow.kt
