+package com.jumblemint.cows.data.dao
+
+import androidx.room.*
+import com.jumblemint.cows.data.model.User
+import kotlinx.coroutines.flow.Flow
+
+@Dao
+interface UserDao {
+ 
+ @Query("SELECT * FROM users WHERE uid = :uid LIMIT 1")
+ suspend fun getUserById(uid: String): User?
+ 
+ @Query("SELECT * FROM users WHERE uid = :uid LIMIT 1")
+ fun getUserByIdFlow(uid: String): Flow<User?>
+ 
+ @Query("SELECT * FROM users")
+ fun getAllUsers(): Flow<List<User>>
+ 
+ @Insert(onConflict = OnConflictStrategy.REPLACE)
+ suspend fun insertUser(user: User)
+ 
+ @Update
+ suspend fun updateUser(user: User)
+ 
+ @Delete
+ suspend fun deleteUser(user: User)
+ 
+ @Query("UPDATE users SET lastSyncAt = :syncTime WHERE uid = :uid")
+ suspend fun updateLastSync(uid: String, syncTime: Long)
+ 
+ @Query("DELETE FROM users")
+ suspend fun deleteAllUsers()
+}","refToolCallId":"toolu_0151if3GX3BSgkxXauWZh6od"},{"type":"toolCall","toolCallId":"toolu_01CvMMnoSwAGmRdMFXz68n6q","statusText":"Change generated","status":"SUCCESS","context":{"files":[{"path":"app/src/main/java/com/jumblemint/cows/data/dao/HerdDao.kt","fsPath":"C:/Users/jeepi/AndroidStudioProjects/cows/app/src/main/java/com/jumblemint/cows/data/dao/HerdDao.kt"}]},"isHidden":false},{"type":"codeHunk","lineBasedDiff":"--- C:/Users/jeepi/AndroidStudioProjects/cows/app/src/main/java/com/jumblemint/cows/data/dao/HerdDao.kt
