+import android.content.Context
+import com.google.android.gms.auth.api.signin.GoogleSignIn
+import com.google.android.gms.auth.api.signin.GoogleSignInAccount
+import com.google.android.gms.auth.api.signin.GoogleSignInClient
+import com.google.android.gms.auth.api.signin.GoogleSignInOptions
+import com.google.firebase.auth.FirebaseAuth
+import com.google.firebase.auth.FirebaseUser
+import com.google.firebase.auth.GoogleAuthProvider
+import com.jumblemint.cows.R
+import com.jumblemint.cows.data.model.User
+import kotlinx.coroutines.flow.Flow
+import kotlinx.coroutines.flow.MutableStateFlow
+import kotlinx.coroutines.flow.asStateFlow
+import kotlinx.coroutines.tasks.await
+
+class AuthService(private val context: Context) {
+ 
+ private val auth = FirebaseAuth.getInstance()
+ private val _currentUser = MutableStateFlow<User?>(null)
+ val currentUser: Flow<User?> = _currentUser.asStateFlow()
+ 
+ private val _isSignedIn = MutableStateFlow(false)
+ val isSignedIn: Flow<Boolean> = _isSignedIn.asStateFlow()
+ 
+ private val googleSignInClient: GoogleSignInClient by lazy {
+ val gso = GoogleSignInOptions.Builder(GoogleSignInOptions.DEFAULT_SIGN_IN)
+ .requestIdToken(context.getString(R.string.default_web_client_id))
+ .requestEmail()
+ .build()
+ GoogleSignIn.getClient(context, gso)
+ }
+ 
+ init {
+ // Listen to auth state changes
+ auth.addAuthStateListener { firebaseAuth ->
+ val firebaseUser = firebaseAuth.currentUser
+ if (firebaseUser != null) {
+ _currentUser.value = firebaseUser.toUser()
+ _isSignedIn.value = true
+ } else {
+ _currentUser.value = null
+ _isSignedIn.value = false
+ }
+ }
+ }
+ 
+ fun getGoogleSignInClient(): GoogleSignInClient = googleSignInClient
+ 
+ suspend fun signInWithGoogle(account: GoogleSignInAccount): Result<User> {
+ return try {
+ val credential = GoogleAuthProvider.getCredential(account.idToken, null)
+ val result = auth.signInWithCredential(credential).await()
+ val firebaseUser = result.user ?: throw Exception("Firebase user is null")
+ 
+ val user = firebaseUser.toUser()
+ _currentUser.value = user
+ _isSignedIn.value = true
+ 
+ Result.success(user)
+ } catch (e: Exception) {
+ Result.failure(e)
+ }
+ }
+ 
+ suspend fun signOut() {
+ try {
+ auth.signOut()
+ googleSignInClient.signOut().await()
+ _currentUser.value = null
+ _isSignedIn.value = false
+ } catch (e: Exception) {
+ // Log error but don't throw - we want to sign out locally even if remote fails
+ }
+ }
+ 
+ fun getCurrentFirebaseUser(): FirebaseUser? = auth.currentUser
+ 
+ private fun FirebaseUser.toUser(): User {
+ return User(
+ uid = uid,
+ email = email ?: "",
+ displayName = displayName,
+ photoUrl = photoUrl?.toString(),
+ createdAt = System.currentTimeMillis()
+ )
+ }
+}","refToolCallId":"toolu_01GZNCKRbQQ2igJ9hhtQenz3"},{"type":"text","text":"## Step 6: Create Sync Service

