+package com.jumblemint.cows.sync
+
+import com.google.firebase.firestore.FirebaseFirestore
+import com.google.firebase.firestore.ListenerRegistration
+import com.jumblemint.cows.data.model.*
+import com.jumblemint.cows.data.repository.CattleRepository
+import kotlinx.coroutines.flow.Flow
+import kotlinx.coroutines.flow.MutableStateFlow
+import kotlinx.coroutines.flow.asStateFlow
+import kotlinx.coroutines.tasks.await
+import java.util.*
+
+class SyncService(
+ private val repository: CattleRepository,
+ private val firestore: FirebaseFirestore = FirebaseFirestore.getInstance()
+) {
+ 
+ private val _syncStatus = MutableStateFlow(SyncStatus.IDLE)
+ val syncStatus: Flow<SyncStatus> = _syncStatus.asStateFlow()
+ 
+ private var herdListeners = mutableMapOf<String, ListenerRegistration>()
+ 
+ suspend fun syncHerdData(herdId: String, userId: String): Result<Unit> {
+ return try {
+ _syncStatus.value = SyncStatus.SYNCING
+ 
+ // Sync in order: Users -> Herds -> Pastures -> Cows -> Activities -> Notes
+ syncUsers(herdId)
+ syncPastures(herdId, userId)
+ syncCows(herdId, userId)
+ syncActivities(herdId, userId)
+ syncNotes(herdId, userId)
+ 
+ _syncStatus.value = SyncStatus.SUCCESS
+ Result.success(Unit)
+ } catch (e: Exception) {
+ _syncStatus.value = SyncStatus.ERROR
+ Result.failure(e)
+ }
+ }
+ 
+ fun startRealtimeSync(herdId: String) {
+ // Stop existing listeners for this herd
+ stopRealtimeSync(herdId)
+ 
+ val listeners = mutableListOf<ListenerRegistration>()
+ 
+ // Listen to cows changes
+ listeners.add(
+ firestore.collection("herds").document(herdId)
+ .collection("cows")
+ .addSnapshotListener { snapshot, error ->
+ if (error != null) return@addSnapshotListener
+ 
+ snapshot?.documentChanges?.forEach { change ->
+ // Handle real-time updates
+ // This would update local database with changes
+ }
+ }
+ )
+ 
+ // Listen to activities changes
+ listeners.add(
+ firestore.collection("herds").document(herdId)
+ .collection("activities")
+ .addSnapshotListener { snapshot, error ->
+ if (error != null) return@addSnapshotListener
+ 
+ snapshot?.documentChanges?.forEach { change ->
+ // Handle real-time updates
+ }
+ }
+ )
+ 
+ // Store listeners for cleanup
+ herdListeners[herdId] = listeners.first() // Simplified - would store all listeners
+ }
+ 
+ fun stopRealtimeSync(herdId: String) {
+ herdListeners[herdId]?.remove()
+ herdListeners.remove(herdId)
+ }
+ 
+ fun stopAllRealtimeSync() {
+ herdListeners.values.forEach { it.remove() }
+ herdListeners.clear()
+ }
+ 
+ private suspend fun syncUsers(herdId: String) {
+ // Get herd members from Firestore
+ val membersSnapshot = firestore.collection("herds").document(herdId)
+ .collection("members").get().await()
+ 
+ membersSnapshot.documents.forEach { doc ->
+ val userId = doc.getString("userId") ?: return@forEach
+ 
+ // Get user details
+ val userDoc = firestore.collection("users").document(userId).get().await()
+ if (userDoc.exists()) {
+ val user = userDoc.toObject(User::class.java)?.copy(uid = userId)
+ user?.let { repository.insertUser(it) }
+ }
+ }
+ }
+ 
+ private suspend fun syncPastures(herdId: String, userId: String) {
+ // Upload local changes first
+ val localPastures = repository.getAllPasturesForHerd(herdId)
+ localPastures.forEach { pasture ->
+ if (pasture.firestoreId == null || pasture.lastSyncAt == 0L) {
+ // New or unsynced pasture
+ val firestoreId = pasture.firestoreId ?: UUID.randomUUID().toString()
+ val pastureData = pasture.toFirestoreMap(userId)
+ 
+ firestore.collection("herds").document(herdId)
+ .collection("pastures").document(firestoreId)
+ .set(pastureData).await()
+ 
+ // Update local record with Firestore ID
+ repository.updatePasture(pasture.copy(
+ firestoreId = firestoreId,
+ lastSyncAt = System.currentTimeMillis(),
+ updatedBy = userId
+ ))
+ }
+ }
+ 
+ // Download remote changes
+ val remoteSnapshot = firestore.collection("herds").document(herdId)
+ .collection("pastures").get().await()
+ 
+ remoteSnapshot.documents.forEach { doc ->
+ val remotePasture = doc.toObject(Pasture::class.java)?.copy(
+ firestoreId = doc.id,
+ lastSyncAt = System.currentTimeMillis()
+ )
+ remotePasture?.let { repository.insertPasture(it) }
+ }
+ }
+ 
+ private suspend fun syncCows(herdId: String, userId: String) {
+ // Similar implementation for cows
+ val localCows = repository.getAllCowsForHerd(herdId)
+ localCows.forEach { cow ->
+ if (cow.firestoreId == null || cow.lastSyncAt == 0L) {
+ val firestoreId = cow.firestoreId ?: UUID.randomUUID().toString()
+ val cowData = cow.toFirestoreMap(userId)
+ 
+ firestore.collection("herds").document(herdId)
+ .collection("cows").document(firestoreId)
+ .set(cowData).await()
+ 
+ repository.updateCow(cow.copy(
+ firestoreId = firestoreId,
+ lastSyncAt = System.currentTimeMillis(),
+ updatedBy = userId
+ ))
+ }
+ }
+ 
+ // Download remote changes
+ val remoteSnapshot = firestore.collection("herds").document(herdId)
+ .collection("cows").get().await()
+ 
+ remoteSnapshot.documents.forEach { doc ->
+ val remoteCow = doc.toObject(Cow::class.java)?.copy(
+ firestoreId = doc.id,
+ lastSyncAt = System.currentTimeMillis()
+ )
+ remoteCow?.let { repository.insertCow(it) }
+ }
+ }
+ 
+ private suspend fun syncActivities(herdId: String, userId: String) {
+ // Similar implementation for activities
+ val localActivities = repository.getAllActivitiesForHerd(herdId)
+ localActivities.forEach { activity ->
+ if (activity.firestoreId == null || activity.lastSyncAt == 0L) {
+ val firestoreId = activity.firestoreId ?: UUID.randomUUID().toString()
+ val activityData = activity.toFirestoreMap(userId)
+ 
+ firestore.collection("herds").document(herdId)
+ .collection("activities").document(firestoreId)
+ .set(activityData).await()
+ 
+ repository.updateActivity(activity.copy(
+ firestoreId = firestoreId,
+ lastSyncAt = System.currentTimeMillis(),
+ updatedBy = userId
+ ))
+ }
+ }
+ 
+ // Download remote changes
+ val remoteSnapshot = firestore.collection("herds").document(herdId)
+ .collection("activities").get().await()
+ 
+ remoteSnapshot.documents.forEach { doc ->
+ val remoteActivity = doc.toObject(Activity::class.java)?.copy(
+ firestoreId = doc.id,
+ lastSyncAt = System.currentTimeMillis()
+ )
+ remoteActivity?.let { repository.insertActivity(it) }
+ }
+ }
+ 
+ private suspend fun syncNotes(herdId: String, userId: String) {
+ // Similar implementation for notes
+ val localNotes = repository.getAllNotesForHerd(herdId)
+ localNotes.forEach { note ->
+ if (note.firestoreId == null || note.lastSyncAt == 0L) {
+ val firestoreId = note.firestoreId ?: UUID.randomUUID().toString()
+ val noteData = note.toFirestoreMap(userId)
+ 
+ firestore.collection("herds").document(herdId)
+ .collection("notes").document(firestoreId)
+ .set(noteData).await()
+ 
+ repository.updateNote(note.copy(
+ firestoreId = firestoreId,
+ lastSyncAt = System.currentTimeMillis(),
+ updatedBy = userId
+ ))
+ }
+ }
+ 
+ // Download remote changes
+ val remoteSnapshot = firestore.collection("herds").document(herdId)
+ .collection("notes").get().await()
+ 
+ remoteSnapshot.documents.forEach { doc ->
+ val remoteNote = doc.toObject(Note::class.java)?.copy(
+ firestoreId = doc.id,
+ lastSyncAt = System.currentTimeMillis()
+ )
+ remoteNote?.let { repository.insertNote(it) }
+ }
+ }
+}
+
+enum class SyncStatus {
+ IDLE, SYNCING, SUCCESS, ERROR
+}
+
+// Extension functions to convert entities to Firestore maps
+private fun Cow.toFirestoreMap(userId: String): Map<String, Any?> {
+ return mapOf(
+ "name" to name,
+ "tagNumber" to tagNumber,
+ "tagColor" to tagColor,
+ "birthDate" to birthDate?.toString(),
+ "gender" to gender.name,
+ "classification" to classification.name,
+ "colorMarkings" to colorMarkings,
+ "motherId" to motherId,
+ "fatherId" to fatherId,
+ "status" to status.name,
+ "pastureId" to pastureId,
+ "photos" to photos,
+ "isWatched" to isWatched,
+ "herdId" to herdId,
+ "isDeleted" to isDeleted,
+ "createdBy" to (createdBy ?: userId),
+ "updatedBy" to userId,
+ "updatedAt" to System.currentTimeMillis()
+ )
+}
+
+private fun Activity.toFirestoreMap(userId: String): Map<String, Any?> {
+ return mapOf(
+ "cowId" to cowId,
+ "date" to date.toString(),
+ "activityType" to activityType.name,
+ "notes" to notes,
+ "fromPastureId" to fromPastureId,
+ "toPastureId" to toPastureId,
+ "details" to details,
+ "groupId" to groupId,
+ "herdId" to herdId,
+ "isDeleted" to isDeleted,
+ "createdBy" to (createdBy ?: userId),
+ "updatedBy" to userId,
+ "updatedAt" to System.currentTimeMillis()
+ )
+}
+
+private fun Pasture.toFirestoreMap(userId: String): Map<String, Any?> {
+ return mapOf(
+ "name" to name,
+ "description" to description,
+ "sizeAcres" to sizeAcres,
+ "herdId" to herdId,
+ "isDeleted" to isDeleted,
+ "createdBy" to (createdBy ?: userId),
+ "updatedBy" to userId,
+ "updatedAt" to System.currentTimeMillis()
+ )
+}
+
+private fun Note.toFirestoreMap(userId: String): Map<String, Any?> {
+ return mapOf(
+ "title" to title,
+ "text" to text,
+ "timestamp" to timestamp,
+ "herdId" to herdId,
+ "isDeleted" to isDeleted,
+ "createdBy" to (createdBy ?: userId),
+ "updatedBy" to userId,
+ "updatedAt" to System.currentTimeMillis()
+ )
+}","refToolCallId":"toolu_01QpvnsXwwK2xqdjSWTN1VYD"},{"type":"text","text":"## Step 7: Update Repository for Multi-User Support

