+ }
+ },
+ confirmButton = {
+ TextButton(
+ onClick = { onConfirm(name, description) },
+ enabled = name.isNotBlank()
+ ) {
+ Text("Create")
+ }
+ },
+ dismissButton = {
+ TextButton(onClick = onDismiss) {
+ Text("Cancel")
+ }
+ }
+ )
