rEach %7B change -%3E%0D%0A // Handle real-time updates%0D%0A // This would update local database with changes%0D%0A %7D%0D%0A %7D%0D%0A )%0D%0A %0D%0A // Listen to activities changes%0D%0A listeners.add(%0D%0A firestore.collection(%22herds%22).document(herdId)%0D%0A .collection(%22activities%22)%0D%0A .addSnapshotListener %7B snapshot, error -%3E%0D%0A if (error != null) return@addSnapshotListener%0D%0A %0D%0A snapshot?.documentChanges?.forEach %7B change -%3E%0D%0A // Handle real-time updates%0D%0A %7D%0D%0A %7D%0D%0A )%0D%0A %0D%0A // Store listeners for cleanup%0D%0A herdListeners%5BherdId%5D = listeners.first() // Simplified - would store all listeners%0D%0A %7D%0D%0A %0D%0A fun stopRealtimeSync(herdId: String) %7B%0D%0A herdListeners%5BherdId%5D?.remove()%0D%0A herdListeners.remove(herdId)%0D%0A %7D%0D%0A %0D%0A fun stopAllRealtimeSync() %7B%0D%0A herdListeners.values.forEach %7B it.remove() %7D%0D%0A herdListeners.clear()%0D%0A %7D%0D%0A %0D%0A private suspend fun syncUsers(herdId: String) %7B%0D%0A // Get herd members from Firestore%0D%0A val membersSnapshot = firestore.collection(%22herds%22).document(herdId)%0D%0A .collection(%22members%22).get().await()%0D%0A %0D%0A membersSnapshot.documents.forEach %7B doc -%3E%0D%0A val userId = doc.getString(%22userId%22) ?: return@forEach%0D%0A %0D%0A // Get user details%0D%0A val userDoc = firestore.collection(%22users%22).document(userId).get().await()%0D%0A if (userDoc.exists()) %7B%0D%0A val user = userDoc.toObject(User::class.java)?.copy(uid = userId)%0D%0A user?.let %7B repository.insertUser(it) %7D%0D%0A %7D%0D%0A %7D%0D%0A %7D%0D%0A %0D%0A private suspend fun syncPastures(herdId: String, userId: String) %7B%0D%0A // Upload local changes first%0D%0A val localPastures = repository.getAllPasturesForHerd(herdId)%0D%0A localPastures.forEach %7B pasture -%3E%0D%0A if (pasture.firestoreId == null %7C%7C pasture.lastSyncAt == 0L) %7B%0D%0A // New or unsynced pasture%0D%0A val firestoreId = pasture.firestoreId ?: UUID.randomUUID().toString()%0D%0A val pastureData = pasture.toFirestoreMap(userId)%0D%0A %0D%0A firestore.collection(%22herds%22).document(herdId)%0D%0A .collection(%22pastures%22).document(firestoreId)%0D%0A .set(pastureData).await()%0D%0A %0D%0A // Update local record with Firestore ID%0D%0A repository.updatePasture(pasture.copy(%0D%0A firestoreId = firestoreId,%0D%0A lastSyncAt = System.currentTimeMillis(),%0D%0A updatedBy = userId%0D%0A ))%0D%0A %7D%0D%0A %7D%0D%0A %0D%0A // Download remote changes%0D%0A val remoteSnapshot = firestore.collection(%22herds%22).document(herdId)%0D%0A .collection(%22pastures%22).get().await()%0D%0A %0D%0A remoteSnapshot.documents.forEach %7B doc -%3E%0D%0A val remotePasture = doc.toObject(Pasture::class.java)?.copy(%0D%0A firestoreId = doc.id,%0D%0A lastSyncAt = System.currentTimeMillis()%0D%0A )%0D%0A remotePasture?.let %7B repository.insertPasture(it) %7D%0D%0A %7D%0D%0A %7D%0D%0A %0D%0A private suspend fun syncCows(herdId: String, userId: String) %7B%0D%0A // Similar implementation for cows%0D%0A val localCows = repository.getAllCowsForHerd(herdId)%0D%0A localCows.forEach %7B cow -%3E%0D%0A if (cow.firestoreId == null %7C%7C cow.lastSyncAt == 0L) %7B%0D%0A val firestoreId = cow.firestoreId ?: UUID.randomUUID().toString()%0D%0A val cowData = cow.toFirestoreMap(userId)%0D%0A %0D%0A firestore.collection(%22herds%22).document(herdId)%0D%0A .collection(%22cows%22).document(firestoreId)%0D%0A .set(cowData).await()%0D%0A %0D%0A repository.updateCow(cow.copy(%0D%0A firestoreId = firestoreId,%0D%0A lastSyncAt = System.currentTimeMillis(),%0D%0A updatedBy = userId%0D%0A ))%0D%0A %7D%0D%0A %7D%0D%0A %0D%0A // Download remote changes%0D%0A val remoteSnapshot = firestore.collection(%22herds%22).document(herdId)%0D%0A .collection(%22cows%22).get().await()%0D%0A %0D%0A remoteSnapshot.documents.forEach %7B doc -%3E%0D%0A val remoteCow = doc.toObject(Cow::class.java)?.copy(%0D%0A firestoreId = doc.id,%0D%0A lastSyncAt = System.currentTimeMillis()%0D%0A )%0D%0A remoteCow?.let %7B repository.insertCow(it) %7D%0D%0A %7D%0D%0A %7D%0D%0A %0D%0A private suspend fun syncActivities(herdId: String, userId: String) %7B%0D%0A // Similar implementation for activities%0D%0A val localActivities = repository.getAllActivitiesForHerd(herdId)%0D%0A localActivities.forEach %7B activity -%3E%0D%0A if (activity.firestoreId == null %7C%7C activity.lastSyncAt == 0L) %7B%0D%0A val firestoreId = activity.firestoreId ?: UUID.randomUUID().toString()%0D%0A val activityData = activity.toFirestoreMap(userId)%0D%0A %0D%0A firestore.collection(%22herds%22).document(herdId)%0D%0A .collection(%22activities%22).document(firestoreId)%0D%0A .set(activityData).await()%0D%0A %0D%0A repository.updateActivity(activity.copy(%0D%0A firestoreId = firestoreId,%0D%0A lastSyncAt = System.currentTimeMillis(),%0D%0A updatedBy = userId%0D%0A ))%0D%0A %7D%0D%0A %7D%0D%0A %0D%0A // Download remote changes%0D%0A val remoteSnapshot = firestore.collection(%22herds%22).document(herdId)%0D%0A .collection(%22activities%22).get().await()%0D%0A %0D%0A remoteSnapshot.documents.forEach %7B doc -%3E%0D%0A val remoteActivity = doc.toObject(Activity::class.java)?.copy(%0D%0A firestoreId = doc.id,%0D%0A lastSyncAt = System.currentTimeMillis()%0D%0A )%0D%0A remoteActivity?.let %7B repository.insertActivity(it) %7D%0D%0A %7D%0D%0A %7D%0D%0A %0D%0A private suspend fun syncNotes(herdId: String, userId: String) %7B%0D%0A // Similar implementation for notes%0D%0A val localNotes = repository.getAllNotesForHerd(herdId)%0D%0A localNotes.forEach %7B note -%3E%0D%0A if (note.firestoreId == null %7C%7C note.lastSyncAt == 0L) %7B%0D%0A val firestoreId = note.firestoreId ?: UUID.randomUUID().toString()%0D%0A val noteData = note.toFirestoreMap(userId)%0D%0A %0D%0A firestore.collection(%22herds%22).document(herdId)%0D%0A .collection(%22notes%22).document(firestoreId)%0D%0A .set(noteData).await()%0D%0A %0D%0A repository.updateNote(note.copy(%0D%0A firestoreId = firestoreId,%0D%0A lastSyncAt =