 %7D%0D%0A %0D%0A Spacer(modifier = Modifier.height(8.dp))%0D%0A %0D%0A Row(%0D%0A verticalAlignment = Alignment.CenterVertically%0D%0A ) %7B%0D%0A Icon(%0D%0A Icons.Default.Group,%0D%0A contentDescription = null,%0D%0A modifier = Modifier.size(16.dp),%0D%0A tint = MaterialTheme.colorScheme.onSurfaceVariant%0D%0A )%0D%0A Spacer(modifier = Modifier.width(4.dp))%0D%0A Text(%0D%0A text = %22$memberCount member$%7Bif (memberCount != 1) %22s%22 else %22%22%7D%22,%0D%0A style = MaterialTheme.typography.bodySmall,%0D%0A color = MaterialTheme.colorScheme.onSurfaceVariant%0D%0A )%0D%0A %7D%0D%0A %7D%0D%0A %7D%0D%0A%7D%0D%0A%0D%0A@Composable%0D%0Aprivate fun CreateHerdDialog(%0D%0A onDismiss: () -%3E Unit,%0D%0A onConfirm: (String, String) -%3E Unit%0D%0A) %7B%0D%0A var name by remember %7B mutableStateOf(%22%22) %7D%0D%0A var description by remember %7B mutableStateOf(%22%22) %7D%0D%0A %0D%0A AlertDialog(%0D%0A onDismissRequest = onDismiss,%0D%0A title = %7B Text(%22Create New Herd%22) %7D,%0D%0A text = %7B%0D%0A Column %7B%0D%0A OutlinedTextField(%0D%0A value = name,%0D%0A onValueChange = %7B name = it %7D,%0D%0A label = %7B Text(%22Herd Name%22) %7D,%0D%0A modifier = Modifier.fillMaxWidth()%0D%0A )%0D%0A Spacer(modifier = Modifier.height(8.dp))%0D%0A OutlinedTextField(%0D%0A value = description,%0D%0A onValueChange = %7B description = it %7D,%0D%0A label = %7B Text(%22Description (Optional)%22) %7D,%0D%0A modifier = Modifier.fillMaxWidth(),%0D%0A maxLines = 3%0D%0A )%0D%0A %7D%0D%0A %7D,%0D%0A confirmButton = %7B%0D%0A TextButton(%0D%0A onClick = %7B onConfirm(name, description) %7D,%0D%0A enabled = name.isNotBlank()%0D%0A ) %7B%0D%0A Text(%22Create%22)%0D%0A %7D%0D%0A %7D,%0D%0A dismissButton = %7B%0D%0A TextButton(onClick = onDismiss) %7B%0D%0A Text(%22Cancel%22)%0D%0A %7D%0D%0A %7D%0D%0A )%0D%0A%7D
