%0D%0A %7D%0D%0A %0D%0A _uiState.value = _uiState.value.copy(%0D%0A herds = herdsWithRoles,%0D%0A isLoading = false,%0D%0A error = null%0D%0A )%0D%0A %7D.collect %7B %7D%0D%0A %0D%0A %7D catch (e: Exception) %7B%0D%0A _uiState.value = _uiState.value.copy(%0D%0A isLoading = false,%0D%0A error = e.message ?: %22Failed to load herds%22%0D%0A )%0D%0A %7D%0D%0A %7D%0D%0A %7D%0D%0A %0D%0A fun createHerd(name: String, description: String) %7B%0D%0A viewModelScope.launch %7B%0D%0A val currentUser = authService.getCurrentFirebaseUser()%0D%0A if (currentUser == null) %7B%0D%0A _uiState.value = _uiState.value.copy(error = %22User not authenticated%22)%0D%0A return@launch%0D%0A %7D%0D%0A %0D%0A _uiState.value = _uiState.value.copy(isLoading = true)%0D%0A %0D%0A try %7B%0D%0A val herdId = UUID.randomUUID().toString()%0D%0A val herd = Herd(%0D%0A id = herdId,%0D%0A name = name,%0D%0A description = description.takeIf %7B it.isNotBlank() %7D,%0D%0A ownerId = currentUser.uid,%0D%0A createdAt = System.currentTimeMillis(),%0D%0A updatedAt = System.currentTimeMillis()%0D%0A )%0D%0A %0D%0A // Create herd%0D%0A repository.insertHerd(herd)%0D%0A %0D%0A // Add creator as owner%0D%0A val membership = HerdMember(%0D%0A herdId = herdId,%0D%0A userId = currentUser.uid,%0D%0A role = HerdRole.OWNER,%0D%0A joinedAt = System.currentTimeMillis()%0D%0A )%0D%0A repository.insertHerdMember(membership)%0D%0A %0D%0A // Sync to Firestore%0D%0A syncService.syncHerdData(herdId, currentUser.uid)%0D%0A %0D%0A // Reload herds%0D%0A loadUserHerds()%0D%0A %0D%0A %7D catch (e: Exception) %7B%0D%0A _uiState.value = _uiState.value.copy(%0D%0A isLoading = false,%0D%0A error = e.message ?: %22Failed to create herd%22%0D%0A )%0D%0A %7D%0D%0A %7D%0D%0A %7D%0D%0A %0D%0A fun selectHerd(herdId: String) %7B%0D%0A viewModelScope.launch %7B%0D%0A val currentUser = authService.getCurrentFirebaseUser()%0D%0A if (currentUser == null) return@launch%0D%0A %0D%0A _uiState.value = _uiState.value.copy(selectedHerdId = herdId)%0D%0A %0D%0A // Start real-time sync for selected herd%0D%0A syncService.startRealtimeSync(herdId)%0D%0A %0D%0A // Perform initial sync%0D%0A syncService.syncHerdData(herdId, currentUser.uid)%0D%0A %7D%0D%0A %7D%0D%0A %0D%0A fun inviteUser(herdId: String, email: String) %7B%0D%0A // TODO: Implement user invitation system%0D%0A // This would typically involve:%0D%0A // 1. Send invitation email/notification%0D%0A // 2. Create pending invitation record%0D%0A // 3. Handle invitation acceptance%0D%0A %7D%0D%0A %0D%0A fun clearError() %7B%0D%0A _uiState.value = _uiState.value.copy(error = null)%0D%0A %7D%0D%0A%7D%0D%0A%0D%0Adata class HerdUiState(%0D%0A val herds: List%3CHerdWithRole%3E = emptyList(),%0D%0A val selectedHerdId: String? = null,%0D%0A val isLoading: Boolean = false,%0D%0A val error: String? = null%0D%0A)%0D%0A%0D%0Adata class HerdWithRole(%0D%0A val herd: Herd,%0D%0A val role: HerdRole,%0D%0A val memberCount: Int%0D%0A)
