+package com.jumblemint.cows
+
+import android.app.Application
+import com.jumblemint.cows.auth.AuthService
+import com.jumblemint.cows.data.database.CattleDatabase
+import com.jumblemint.cows.data.repository.CattleRepository
+import com.jumblemint.cows.sync.SyncService
+
+class CattleApplication : Application() {
+ 
+ // Database
+ val database by lazy { CattleDatabase.getDatabase(this) }
+ 
+ // Repository
+ val repository by lazy {
+ CattleRepository(
+ cowDao = database.cowDao(),
+ pastureDao = database.pastureDao(),
+ activityDao = database.activityDao(),
+ settingsDao = database.settingsDao(),
+ noteDao = database.noteDao(),
+ userDao = database.userDao(),
+ herdDao = database.herdDao(),
+ herdMemberDao = database.herdMemberDao()
+ )
+ }
+ 
+ // Auth Service
+ val authService by lazy { AuthService(this) }
+ 
+ // Sync Service
+ val syncService by lazy { SyncService(repository) }
+}","refToolCallId":"toolu_01QwWfFtUjSqxAc26ByesESD"},{"type":"text","text":"Now I need to register this in the AndroidManifest.xml:"},{"type":"toolCall","toolCallId":"toolu_01UnRdT7iS6Moyfm1B1v82mX","statusText":"Viewed file (lines 1:27)","status":"SUCCESS","context":{"files":[{"path":"app/src/main/AndroidManifest.xml","fsPath":"C:/Users/jeepi/AndroidStudioProjects/cows/app/src/main/AndroidManifest.xml"}]},"isHidden":false},{"type":"toolCall","toolCallId":"toolu_01JRLsucsABvsJtfdTPRNyx2","statusText":"Change generated","status":"SUCCESS","context":{"files":[{"path":"app/src/main/AndroidManifest.xml","fsPath":"C:/Users/jeepi/AndroidStudioProjects/cows/app/src/main/AndroidManifest.xml"}]},"isHidden":false},{"type":"codeHunk","lineBasedDiff":"--- C:/Users/jeepi/AndroidStudioProjects/cows/app/src/main/AndroidManifest.xml
