+package com.jumblemint.cows.ui.viewmodel
+
+import androidx.lifecycle.ViewModel
+import androidx.lifecycle.ViewModelProvider
+import com.jumblemint.cows.auth.AuthService
+import com.jumblemint.cows.data.repository.CattleRepository
+
+class AuthViewModelFactory(
+ private val authService: AuthService,
+ private val repository: CattleRepository
+) : ViewModelProvider.Factory {
+ override fun <T : ViewModel> create(modelClass: Class<T>): T {
+ if (modelClass.isAssignableFrom(AuthViewModel::class.java)) {
+ @Suppress("UNCHECKED_CAST")
+ return AuthViewModel(authService, repository) as T
+ }
+ throw IllegalArgumentException("Unknown ViewModel class")
+ }
+}","refToolCallId":"toolu_016Y7bj2b48FPhpFohjQdNFv"},{"type":"toolCall","toolCallId":"toolu_01YV88NpwWC1snvYvZhETLSU","statusText":"Change generated","status":"SUCCESS","context":{"files":[{"path":"app/src/main/java/com/jumblemint/cows/ui/viewmodel/HerdViewModelFactory.kt","fsPath":"C:/Users/jeepi/AndroidStudioProjects/cows/app/src/main/java/com/jumblemint/cows/ui/viewmodel/HerdViewModelFactory.kt"}]},"isHidden":false},{"type":"codeHunk","lineBasedDiff":"--- C:/Users/jeepi/AndroidStudioProjects/cows/app/src/main/java/com/jumblemint/cows/ui/viewmodel/HerdViewModelFactory.kt
