import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.jumblemint.cows.data.model.Pasture
import com.jumblemint.cows.data.repository.CattleRepository
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.launch

class PasturesViewModel(
 private val repository: CattleRepository
) : ViewModel() {

 private val _uiState = MutableStateFlow(PasturesUiState())
 val uiState: StateFlow<PasturesUiState> = _uiState.asStateFlow()

 init {
 loadPastures()
 }

 private fun loadPastures() {
 viewModelScope.launch {
 try {
 // Get current pastures
 val pastures = repository.getAllPastures().first()

 // Load cow counts for each pasture
 val cowCounts = mutableMapOf<Long, Int>()
 pastures.forEach { pasture ->
 val cows = repository.getCowsByPasture(pasture.id).first()
 cowCounts[pasture.id] = cows.size
 }

 _uiState.value = _uiState.value.copy(
 pastures = pastures,
 pasturesCowCount = cowCounts,
 isLoading = false
 )
 } catch (e: Exception) {
 _uiState.value = _uiState.value.copy(
 error = e.message,
 isLoading = false
 )
 }
 }
 }

 fun addPasture(name: String, acreage: Double?) {
 viewModelScope.launch {
 try {
 val pasture = Pasture(
 name = name,
 acreage = acreage
 )
 repository.insertPasture(pasture)
 } catch (e: Exception) {
 _uiState.value = _uiState.value.copy(error = e.message)
 }
 }
 }
}

data class PasturesUiState(
 val pastures: List<Pasture> = emptyList(),
 val pasturesCowCount: Map<Long, Int> = emptyMap(),
 val isLoading: Boolean = true,
 val error: String? = null
)","language":"kotlin"},"codebaseEnabled":true},"createdAt":1756091220879,"isInternal":false,"rawContent":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Continue. You were in the middle of request:"}]},{"type":"paragraph","content":[{"type":"text","text":"I still can't choose a date for birthdate when entering cow."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"The pastures screen is working, but i want it to list total head, as well as how many cows, bulls and calves on the card, then be able to click the pasture to see see a list of cows, either on a new screen or on the cows screen filtered by pasture"}]},{"type":"paragraph","content":[{"type":"text","text":"Avoid repeating steps you've already taken."}]}]},"isHidden":true,"autoAppliedRules":[]},{"id":"8988dbf7-c0cf-40f2-b4f7-b02ebd04ce12","role":"assistant","content":[{"type":"text","text":"Let me test the app to see if there are any remaining issues with the changes I made. Let me check if there are any compilation errors or missing imports:"},{"type":"toolCall","toolCallId":"toolu_01MPQ5pn5zp1JRia9ARtjBac","status":"IN_PROGRESS","isHidden":true,"localResult":"{"status":"ERROR","exitCode":1,"output":"\u001b[?9001h\u001b[?1004h\u001b[?25l\u001b[2J\u001b[m\u001b[38;5;9m\u001b[HC:\\Users\\jeepi\\AppData\\Local\\Temp\\Zencoder-e44226c6-1ded-4125-8811-680b9376e88d.ps1 : File \r\nC:\\Users\\jeepi\\AppData\\Local\\Temp\\Zencoder-e44226c6-1ded-4125-8811-680b9376e88d.ps1 cannot be loaded because running \r\nscripts is disabled on this system. For more information, see about_Execution_Policies at \r\nhttps:/go.microsoft.com/fwlink/?LinkID=135170.\r\nAt line:1 char:1\r\n+ C:\\Users\\jeepi\\AppData\\Local\\Temp\\Zencoder-e44226c6-1ded-4125-8811-68 ...\r\n+ ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\r\n + CategoryInfo : SecurityError: (:) [], PSSecurityException\r\n + FullyQualifiedErrorId : UnauthorizedAccess\r\n\u001b]0;C:\\Windows\