import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.jumblemint.cows.data.model.Pasture
import com.jumblemint.cows.data.model.Gender
import com.jumblemint.cows.data.model.Classification
import com.jumblemint.cows.data.repository.CattleRepository
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.launch

class PasturesViewModel(
 private val repository: CattleRepository
) : ViewModel() {

 private val _uiState = MutableStateFlow(PasturesUiState())
 val uiState: StateFlow<PasturesUiState> = _uiState.asStateFlow()

 init {
 loadPastures()
 }

 private fun loadPastures() {
 viewModelScope.launch {
 try {
 // Get current pastures
 val pastures = repository.getAllPastures().first()

 // Load detailed cattle counts for each pasture
 val pastureDetails = mutableMapOf<Long, PastureDetails>()
 pastures.forEach { pasture ->
 val cows = repository.getCowsByPasture(pasture.id).first()

 val totalCount = cows.size
 val cowCount = cows.count { it.gender == Gender.FEMALE && it.classification == Classification.COW }
 val bullCount = cows.count { it.gender == Gender.MALE && it.classification == Classification.BULL }
 val calfCount = cows.count { it.classification == Classification.CALF }
 val heiferCount = cows.count { it.gender == Gender.FEMALE && it.classification == Classification.HEIFER }
 val steerCount = cows.count { it.gender == Gender.MALE && it.classification == Classification.STEER }

 pastureDetails[pasture.id] = PastureDetails(
 totalCount = totalCount,
 cowCount = cowCount,
 bullCount = bullCount,
 calfCount = calfCount,
 heiferCount = heiferCount,
 steerCount = steerCount
 )
 }

 _uiState.value = _uiState.value.copy(
 pastures = pastures,
 pastureDetails = pastureDetails,
 isLoading = false
 )
 } catch (e: Exception) {
 _uiState.value = _uiState.value.copy(
 error = e.message,
 isLoading = false
 )
 }
 }
 }

 fun addPasture(name: String, acreage: Double?) {
 viewModelScope.launch {
 try {
 val pasture = Pasture(
 name = name,
 acreage = acreage
 )
 repository.insertPasture(pasture)
 loadPastures() // Refresh the data after adding
 } catch (e: Exception) {
 _uiState.value = _uiState.value.copy(error = e.message)
 }
 }
 }
}

data class PasturesUiState(
 val pastures: List<Pasture> = emptyList(),
 val pastureDetails: Map<Long, PastureDetails> = emptyMap(),
 val isLoading: Boolean = true,
 val error: String? = null
)

data class PastureDetails(
 val totalCount: Int,
 val cowCount: Int,
 val bullCount: Int,
 val calfCount: Int,
 val heiferCount: Int,
 val steerCount: Int
)","language":"kotlin"},"codebaseEnabled":true},"createdAt":1756092005938,"isInternal":false,"rawContent":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"well crap. I still can't add a birthdate (i can't type and dont' get a calendar selector)"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"But all the tabs are gone too so I only have the cows screen"}]}]},"autoAppliedRules":[]},{"id":"6f4f721d-2b97-4f1b-8397-47b1c59caf95","role":"assistant","content":[{"type":"text","text":"Let me fix these critical issues. First, let me check what happened to the navigation tabs:"},{"type":"toolCall","toolCallId":"toolu_01XMaN5WEiXgbbzTx9h5g22g","statusText":"Viewed file (lines 1:87)","status":"SUCCESS","context":{"files":[{"path":"app/src/main/java/com/jumblemint/cows/MainActivity.kt","fsPath":"C:/Users/jeepi/AndroidStudioProjects/cows/app/src/main/java/com/jumblemint/cows/MainActivity.kt"}]},"isHidden":false},{"type":"text","text":"I see the issue! The bottom navigation is only showing when the current route exactly matches the main screen routes, but I added a parameterized route for cows that doesn't match. Let me fix this:"},{"type":"toolCall","toolCallId":"toolu_01W9WFtohhgK9x5FG9mqC6AF","statusText":"Change generated","status":"SUCCESS","context":{"files":[{"path":"app/src/main/java/com/jumblemint/cows/MainActivity.kt","fsPath":"C:/Users/jeepi/AndroidStudioProjects/cows/app/src/main/java/com/jumblemint/cows/MainActivity.kt"}]},"isHidden":false},{"type":"codeHunk","lineBasedDiff":"--- C:/Users/jeepi/AndroidStudioProjects/cows/app/src/main/java/com/jumblemint/cows/MainActivity.kt
