 label = { Text("Activity Types") },
 placeholder = { Text("MOVED, WEANED, SOLD, DECEASED...") },
 modifier = Modifier.fillMaxWidth(),
 minLines = 3
 )
 }
 },
 confirmButton = {
 TextButton(
 onClick = {
