nd fun undoDeleteCow(cow: Cow) %7B%0D%0A // Simple undo: reinsert the previous item (id may autogenerate)%0D%0A repository.insertCow(cow.copy(id = 0))%0D%0A %7D%0D%0A%7D%0D%0A%0D%0Adata class PastureDetailUiState(%0D%0A val pasture: Pasture? = null,%0D%0A val activeCows: List%3CCow%3E = emptyList(),%0D%0A val classificationBreakdown: Map%3CClassification, Int%3E = emptyMap(),%0D%0A val isLoading: Boolean = true,%0D%0A val error: String? = null%0D%0A)
