atus != SyncStatus.SYNCING) %7B%0D%0A coroutineScope.launch %7B%0D%0A application.authService.startUserSync(application.syncService)%0D%0A %7D%0D%0A %7D%0D%0A %7D%0D%0A )%0D%0A %7D%0D%0A %0D%0A item %7B%0D%0A AccountManagementCard(%0D%0A title = %22Manual Sync%22,%0D%0A subtitle = %22Force sync all your data now%22,%0D%0A icon = Icons.Default.Refresh,%0D%0A onClick = %7B%0D%0A coroutineScope.launch %7B%0D%0A application.authService.startUserSync(application.syncService)%0D%0A %7D%0D%0A %7D%0D%0A )%0D%0A %7D%0D%0A %7D%0D%0A %0D%0A // Account Actions Section%0D%0A item %7B%0D%0A Text(%0D%0A text = %22Account Actions%22,%0D%0A style = MaterialTheme.typography.titleMedium,%0D%0A fontWeight = FontWeight.Bold%0D%0A )%0D%0A %7D%0D%0A %0D%0A if (currentUser?.isLocalUser == false) %7B%0D%0A item %7B%0D%0A AccountManagementCard(%0D%0A title = %22Switch to Local Account%22,%0D%0A subtitle = %22Use app without Google account sync%22,%0D%0A icon = Icons.Default.PersonOff,%0D%0A onClick = %7B%0D%0A coroutineScope.launch %7B%0D%0A application.authService.signOut()%0D%0A onNavigateBack()%0D%0A %7D%0D%0A %7D%0D%0A )%0D%0A %7D%0D%0A %7D%0D%0A %0D%0A item %7B%0D%0A AccountManagementCard(%0D%0A title = if (currentUser?.isLocalUser == false) %22Sign Out%22 else %22Reset Local Account%22,%0D%0A subtitle = if (currentUser?.isLocalUser == false) %0D%0A %22Sign out and switch to local account%22 %0D%0A else %0D%0A %22Clear local user data and create new local account%22,%0D%0A icon = Icons.Default.Logout,%0D%0A onClick = %7B showSignOutDialog = true %7D%0D%0A )%0D%0A %7D%0D%0A %0D%0A // Account Information Section%0D%0A item %7B%0D%0A Text(%0D%0A text = %22Account Information%22,%0D%0A style = MaterialTheme.typography.titleMedium,%0D%0A fontWeight = FontWeight.Bold%0D%0A )%0D%0A %7D%0D%0A %0D%0A item %7B%0D%0A Card(%0D%0A modifier = Modifier.fillMaxWidth(),%0D%0A colors = CardDefaults.cardColors(%0D%0A containerColor = MaterialTheme.colorScheme.surfaceVariant%0D%0A )%0D%0A ) %7B%0D%0A Column(%0D%0A modifier = Modifier.padding(16.dp)%0D%0A ) %7B%0D%0A AccountInfoRow(%22User ID%22, currentUser?.uid ?: %22Unknown%22)%0D%0A AccountInfoRow(%22Account Type%22, if (currentUser?.isLocalUser == true) %22Local%22 else %22Google%22)%0D%0A AccountInfoRow(%22Created%22, %22Recently%22) // You could format the createdAt timestamp%0D%0A if (currentUser?.isLocalUser == false) %7B%0D%0A AccountInfoRow(%22Last Sync%22, if (currentUser?.lastSyncAt != 0L) %22Recently%22 else %22Never%22)%0D%0A %7D%0D%0A %7D%0D%0A %7D%0D%0A %7D%0D%0A %7D%0D%0A %7D%0D%0A %0D%0A // Sign Out Confirmation Dialog%0D%0A if (showSignOutDialog) %7B%0D%0A AlertDialog(%0D%0A onDismissRequest = %7B showSignOutDialog = false %7D,%0D%0A title = %7B %0D%0A Text(%0D%0A if (currentUser?.isLocalUser == false) %22Sign Out?%22 else %22Reset Local Account?%22%0D%0A ) %0D%0A %7D,%0D%0A text = %7B %0D%0A Text(%0D%0A if (currentUser?.isLocalUser == false)%0D%0A %22You will be signed out and switched to a local account. Your data will remain synced to your Google account.%22%0D%0A else%0D%0A %22This will clear your local user data and create a new local account. Your cattle data will remain.%22%0D%0A )%0D%0A %7D,%0D%0A confirmButton = %7B%0D%0A TextButton(%0D%0A onClick = %7B%0D%0A coroutineScope.launch %7B%0D%0A application.authService.signOut()%0D%0A showSignOutDialog = false%0D%0A onNavigateBack()%0D%0A %7D%0D%0A %7D%0D%0A ) %7B%0D%0A Text(%22Confirm%22)%0D%0A %7D%0D%0A %7D,%0D%0A dismissButton = %7B%0D%0A TextButton(onClick = %7B showSignOutDialog = false %7D) %7B%0D%0A Text(%22Cancel%22)%0D%0A %7D%0D%0A %7D%0D%0A )%0D%0A %7D%0D%0A%7D%0D%0A%0D%0A@Composable%0D%0Aprivate fun AccountManagementCard(%0D%0A title: String,%0D%0A subtitle: String,%0D%0A icon: androidx.compose.ui.graphics.vector.ImageVector,%0D%0A onClick: () -%3E Unit%0D%0A) %7B%0D%0A Card(%0D%0A onClick = onClick,%0D%0A modifier = Modifier.fillMaxWidth()%0D%0A ) %7B%0D%0A Row(%0D%0A modifier = Modifier%0D%0A .fillMaxWidth()%0D%0A .padding(16.dp),%