 true
 }
 localCow.lastSyncAt < remoteUpdatedAt -> {
 println("Downloading newer remote cow: ${data["name"]}")
 true
 }
 else -> false
 }

 if (shouldDownload) {
 val remoteCow = Cow(
 id = localCow?.id ?: (data["id"] as? Number)?.toLong() ?: 0L,
