import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.jumblemint.cows.auth.AuthService
import com.jumblemint.cows.data.model.Herd
import com.jumblemint.cows.data.model.HerdMember
import com.jumblemint.cows.data.model.HerdRole
import com.jumblemint.cows.data.repository.CattleRepository
import com.jumblemint.cows.sync.SyncService
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.combine
import kotlinx.coroutines.launch
import java.util.*

class HerdViewModel(
 private val repository: CattleRepository,
 private val authService: AuthService,
 private val syncService: SyncService
) : ViewModel() {

 private val _uiState = MutableStateFlow(HerdUiState())
 val uiState: StateFlow<HerdUiState> = _uiState.asStateFlow()

 init {
 loadUserHerds()
 }

 private fun loadUserHerds() {
 viewModelScope.launch {
 // Get current user (Firebase or local)
 authService.currentUser.collect { currentUser ->
 if (currentUser == null) {
 _uiState.value = _uiState.value.copy(
 isLoading = false,
 error = "User not authenticated"
 )
 return@collect
 }

 _uiState.value = _uiState.value.copy(isLoading = true)

 try {
 // Get herds where user is a member
 combine(
 repository.getHerdsByUser(currentUser.uid),
 repository.getAllActiveHerds()
 ) { memberships, allHerds ->
 val herdsWithRoles = memberships.mapNotNull { membership ->
 val herd = allHerds.find { it.id == membership.herdId }
 if (herd != null) {
 HerdWithRole(
 herd = herd,
 role = membership.role,
 memberCount = 1 // TODO: Get actual member count
 )
 } else null
 }

 _uiState.value = _uiState.value.copy(
 herds = herdsWithRoles,
 isLoading = false,
 error = null
 )
 }.collect { }

 } catch (e: Exception) {
 _uiState.value = _uiState.value.copy(
 isLoading = false,
 error = e.message ?: "Failed to load herds"
 )
 }
 }
 }
 }

 fun createHerd(name: String, description: String) {
 viewModelScope.launch {
 // Get current user (Firebase or local)
 val currentUser = authService.currentUser.value
 if (currentUser == null) {
 _uiState.value = _uiState.value.copy(error = "User not authenticated")
 return@launch
 }

 _uiState.value = _uiState.value.copy(isLoading = true)

 try {
 val herdId = UUID.randomUUID().toString()
 val herd = Herd(
 id = herdId,
 name = name,
 description = description.takeIf { it.isNotBlank() },
 ownerId = currentUser.uid,
 createdAt = System.currentTimeMillis(),
 updatedAt = System.currentTimeMillis()
 )

 // Create herd
 repository.insertHerd(herd)

 // Add creator as owner
 val membership = HerdMember(
 herdId = herdId,
 userId = currentUser.uid,
 role = HerdRole.OWNER,
 joinedAt = System.currentTimeMillis()
 )
 repository.insertHerdMember(membership)

 // Sync to Firestore
 syncService.syncHerdData(herdId, currentUser.uid)

 // Reload herds
 loadUserHerds()

 } catch (e: Exception) {
 _uiState.value = _uiState.value.copy(
 isLoading = false,
 error = e.message ?: "Failed to create herd"
 )
 }
 }
 }

 fun selectHerd(herdId: String) {
 viewModelScope.launch {
 val currentUser = authService.currentUser.value
 if (currentUser == null) return@launch

 _uiState.value = _uiState.value.copy(selectedHerdId = herdId)

 // Start real-time sync for selected herd
 syncService.startRealtimeSync(herdId)

 // Perform initial sync
 syncService.syncHerdData(herdId, currentUser.uid)
 }
 }

 fun inviteUser(herdId: String, email: String) {
 // TODO: Implement user invitation system
 // This would typically involve:
 // 1. Send invitation email/notification
 // 2. Create pending invitation record
 // 3. Handle invitation acceptance
 }

 fun clearError() {
 _uiState.value = _uiState.value.copy(error = null)
 }
}

data class HerdUiState(
 val herds: List<HerdWithRole> = emptyList(),
 val selectedHerdId: String? = null,
 val isLoading: Boolean = false,
 val error: String? = null
)

data class HerdWithRole(
 val herd: Herd,
 val role: HerdRole,
 val memberCount: Int
)","language":"kotlin"},"codebaseEnabled":true,"usedRules":["zen-rules://repo/.zencoder/rules/repo.md"]},"createdAt":1756993729574,"isInternal":false,"rawContent":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"I'm still getting this error:"}]},{"type":"paragraph","content":[{"type":"text","text":"e: file:///C:/Users/jeepi/AndroidStudioProjects/cows/app/src/main/java/com/jumblemint/cows/ui/viewmodel/HerdViewModel.kt:82:55 Unresolved reference: value"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"e: file:///C:/Users/jeepi/AndroidStudioProjects/cows/app/src/main/java/com/jumblemint/cows/ui/viewmodel/HerdViewModel.kt:130:55 Unresolved reference: value"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"I'm thinking of allowing one herd owned by each user, but could allow multiple shared herds to be accessed from other users. However, if it's no more work to offer multiple owned herds we can do that. I did think of making multiple herds a premium feature later"}]}]},"autoAppliedRules":[{"name":"Repository Information Overview","description":"Repository Information Overview","uri":"zen-rules://repo/.zencoder/rules/repo.md","mimeType":"text/markdown","content":"

# Cattle Manager App Information

## Summary
A comprehensive Android application for managing cattle records, built with Jetpack Compose and Room database. The app allows tracking of cattle, pastures, and activities with a modern Material 3 UI.

## Structure
- **app/**: Main application module
 - **src/main/java/com/jumblemint/cows/**: Source code
 - **data/**: Data layer (models, DAOs, database)
 - **ui/**: UI components and screens
 - **navigation/**: Navigation configuration
 - **src/androidTest/**: Instrumentation tests
 - **src/test/**: Unit tests

## Language & Runtime
**Language**: Kotlin
**Version**: 2.0.21
**Build System**: Gradle (Kotlin DSL)
**Package Manager**: Gradle
**JVM Target**: Java 11
**Android SDK**: 
- **Compile SDK**: 36
- **Target SDK**: 36
- **Min SDK**: 30

## Dependencies
**Main Dependencies**:
- Jetpack Compose (2024.09.00)
- Room Database (2.6.1)
- Navigation Compose (2.8.5)
- Lifecycle ViewModel (2.9.2)
- Material 3
- Kotlin Coroutines

**Development Dependencies**:
- JUnit (4.13.2)
- Espresso (3.7.0)
- Compose UI Testing

## Build & Installation
```bash
./gradlew assembleDebug
```
Installation:
```bash
./gradlew installDebug
```

## Testing
**Frameworks**: 
- JUnit for unit tests
- AndroidX Test for instrumentation tests
- Espresso for UI testing

**Test Location**: 
- Unit tests: `app/src/test/`
- Instrumentation tests: `app/src/androidTest/`

**Run Command**:
```bash
./gradlew test # Unit tests
./gradlew connectedCheck # Instrumentation tests
```

## Database Schema
**Database Engine**: Room (SQLite)
**Version**: 2
**Entities**:
- Cows: Animal records with tag numbers, birth dates, gender, etc.
- Pastures: Land management with acreage and assigned animals
- Activities: Events like moves, births, sales with dates and notes
- Settings: Application configuration storage

**Features**:
- Type converters for complex data types
- Migration support
- Foreign key relationships
- DAO pattern for data access","alwaysApply":true}]},{"id":"b283c1ce-679a-4bbe-a8ff-2c78c6982adf","role":"assistant","content":[{"type":"text","text":"I can see the compilation errors in your HerdViewModel. The issue is that you're trying to access `.value` on `authService.currentUser`, but based on the context, `currentUser` is likely a `Flow` or `StateFlow`, not a property with a direct `.value` accessor.

