+package com.jumblemint.cows.data.preferences
+
+import android.content.Context
+import android.content.SharedPreferences
+import kotlinx.coroutines.flow.MutableStateFlow
+import kotlinx.coroutines.flow.StateFlow
+import kotlinx.coroutines.flow.asStateFlow
+
+class HerdPreferences(context: Context) {
+ private val prefs: SharedPreferences = context.getSharedPreferences("herd_prefs", Context.MODE_PRIVATE)
+ 
+ private val _selectedHerdId = MutableStateFlow(getSelectedHerdId())
+ val selectedHerdId: StateFlow<String?> = _selectedHerdId.asStateFlow()
+ 
+ fun getSelectedHerdId(): String? {
+ return prefs.getString(KEY_SELECTED_HERD_ID, null)
+ }
+ 
+ fun setSelectedHerdId(herdId: String?) {
+ prefs.edit().putString(KEY_SELECTED_HERD_ID, herdId).apply()
+ _selectedHerdId.value = herdId
+ }
+ 
+ fun clearSelectedHerd() {
+ prefs.edit().remove(KEY_SELECTED_HERD_ID).apply()
+ _selectedHerdId.value = null
+ }
+ 
+ companion object {
+ private const val KEY_SELECTED_HERD_ID = "selected_herd_id"
+ }
+}","refToolCallId":"toolu_vrtx_014ZxiFuHmqpDuXdTzfzWXKc"},{"type":"text","text":"Now let me add this to the CattleApplication:"},{"type":"toolCall","toolCallId":"toolu_vrtx_01GWMGKmH4P9LGyvRxbwDTiv","statusText":"Viewed file (lines 1:33)","status":"SUCCESS","context":{"files":[{"path":"app/src/main/java/com/jumblemint/cows/CattleApplication.kt","fsPath":"C:/Users/jeepi/AndroidStudioProjects/cows/app/src/main/java/com/jumblemint/cows/CattleApplication.kt"}]},"isHidden":false},{"type":"toolCall","toolCallId":"toolu_vrtx_013DyXd88LKh1BxxGsiU8mWL","statusText":"Change generated","status":"SUCCESS","context":{"files":[{"path":"app/src/main/java/com/jumblemint/cows/CattleApplication.kt","fsPath":"C:/Users/jeepi/AndroidStudioProjects/cows/app/src/main/java/com/jumblemint/cows/CattleApplication.kt"}]},"isHidden":false},{"type":"codeHunk","lineBasedDiff":"--- C:/Users/jeepi/AndroidStudioProjects/cows/app/src/main/java/com/jumblemint/cows/CattleApplication.kt
