import android.content.Context
import android.content.Intent
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.google.android.gms.auth.api.signin.GoogleSignInAccount
import com.jumblemint.cows.auth.AuthService
import com.jumblemint.cows.data.model.User
import com.jumblemint.cows.data.repository.CattleRepository
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

class AuthViewModel(
 private val authService: AuthService,
 private val repository: CattleRepository
) : ViewModel() {

 private val _uiState = MutableStateFlow(AuthUiState())
 val uiState: StateFlow<AuthUiState> = _uiState.asStateFlow()

 init {
 // Listen to auth state changes
 viewModelScope.launch {
 authService.currentUser.collect { user ->
 _uiState.value = _uiState.value.copy(
 currentUser = user,
 isSignedIn = user != null,
 isLoading = false
 )

 // Save user to local database
 user?.let { repository.insertUser(it) }
 }
 }
 }

 fun getGoogleSignInIntent(context: Context): Intent {
 return authService.googleSignInClient.signInIntent
 }

 fun signInWithGoogle(account: GoogleSignInAccount) {
 viewModelScope.launch {
 _uiState.value = _uiState.value.copy(isLoading = true, error = null)

 val result = authService.signInWithGoogle(account)
 result.fold(
 onSuccess = { user ->
 _uiState.value = _uiState.value.copy(
 currentUser = user,
 isSignedIn = true,
 isLoading = false,
 error = null
 )
 },
 onFailure = { exception ->
 _uiState.value = _uiState.value.copy(
 isLoading = false,
 error = exception.message ?: "Sign-in failed"
 )
 }
 )
 }
 }

 fun signOut() {
 viewModelScope.launch {
 authService.signOut()
 _uiState.value = _uiState.value.copy(
 currentUser = null,
 isSignedIn = false,
 error = null
 )
 }
 }

 fun setError(message: String) {
 _uiState.value = _uiState.value.copy(error = message)
 }

 fun clearError() {
 _uiState.value = _uiState.value.copy(error = null)
 }
}

data class AuthUiState(
 val currentUser: User? = null,
 val isSignedIn: Boolean = false,
 val isLoading: Boolean = false,
 val error: String? = null
)","language":"kotlin"},"codebaseEnabled":true,"usedRules":["zen-rules://repo/.zencoder/rules/repo.md"]},"createdAt":1756866018813,"isInternal":false,"rawContent":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Continue. You were in the middle of request:"}]},{"type":"paragraph","content":[{"type":"text","text":"I want google signing to be an optional setting, perhaps even only a premium feature, i want users to be able to use app without signing in"}]},{"type":"paragraph","content":[{"type":"text","text":"Avoid repeating steps you've already taken."}]}]},"isHidden":true,"autoAppliedRules":[]},{"id":"b838e195-e9b9-4b2a-be16-6fff18834748","role":"user","content":[{"type":"text","text":"For now, sign in/sync will be free, but there should be a note during sign in that this feature will possibly be premium in the future"}],"context":{"currentFile":{"path":"app/src/main/java/com/jumblemint/cows/auth/AuthService.kt","fsPath":"C:/Users/jeepi/AndroidStudioProjects/cows/app/src/main/java/com/jumblemint/cows/auth/AuthService.kt","sources":["opened_tab"],"content":"package com.jumblemint.cows.auth

import android.content.Context
import android.content.SharedPreferences
import com.google.android.gms.auth.api.signin.GoogleSignIn
import com.google.android.gms.auth.api.signin.GoogleSignInAccount
import com.google.android.gms.auth.api.signin.GoogleSignInClient
import com.google.android.gms.auth.api.signin.GoogleSignInOptions
import com.google.firebase.auth.FirebaseAuth
import com.google.firebase.auth.FirebaseUser
import com.google.firebase.auth.GoogleAuthProvider
import com.jumblemint.cows.R
import com.jumblemint.cows.data.model.User
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.tasks.await
import java.util.UUID

class AuthService(private val context: Context) {

 private val auth = FirebaseAuth.getInstance()
 private val prefs: SharedPreferences = context.getSharedPreferences("auth_prefs", Context.MODE_PRIVATE)

 private val _currentUser = MutableStateFlow<User?>(null)
 val currentUser: Flow<User?> = _currentUser.asStateFlow()

 private val _isSignedIn = MutableStateFlow(false)
 val isSignedIn: Flow<Boolean> = _isSignedIn.asStateFlow()

 val googleSignInClient: GoogleSignInClient by lazy {
 val gso = GoogleSignInOptions.Builder(GoogleSignInOptions.DEFAULT_SIGN_IN)
 .requestIdToken(context.getString(R.string.default_web_client_id))
 .requestEmail()
 .build()
 GoogleSignIn.getClient(context, gso)
 }

 init {
 // Check for local user first
 val localUser = getLocalUser()
 if (localUser != null) {
 _currentUser.value = localUser
 _isSignedIn.value = true
 } else {
 // Listen to Firebase auth state changes
 auth.addAuthStateListener { firebaseAuth ->
 val firebaseUser = firebaseAuth.currentUser
 if (firebaseUser != null) {
 _currentUser.value = firebaseUser.toUser()
 _isSignedIn.value = true
 } else {
 _currentUser.value = null
 _isSignedIn.value = false
 }
 }
 }
 }

 suspend fun signInWithGoogle(account: GoogleSignInAccount): Result<User> {
 return try {
 val credential = GoogleAuthProvider.getCredential(account.idToken, null)
 val result = auth.signInWithCredential(credential).await()
 val firebaseUser = result.user ?: throw Exception("Firebase user is null")

 val user = firebaseUser.toUser()
 _currentUser.value = user
 _isSignedIn.value = true

 Result.success(user)
 } catch (e: Exception) {
 Result.failure(e)
 }
 }

 suspend fun signOut() {
 try {
 // Clear local user if exists
 if (_currentUser.value?.isLocalUser == true) {
 clearLocalUser()
 } else {
 // Sign out from Firebase
 auth.signOut()
 googleSignInClient.signOut().await()
 }
 _currentUser.value = null
 _isSignedIn.value = false
 } catch (e: Exception) {
 // Log error but don't throw - we want to sign out locally even if remote fails
 }
 }

 fun signInAsLocalUser(displayName: String? = null): User {
 val localUserId = prefs.getString("local_user_id", null) ?: UUID.randomUUID().toString()
 val user = User(
 uid = localUserId,
 email = "",
 displayName = displayName ?: "Local User",
 photoUrl = null,
 createdAt = System.currentTimeMillis(),
 lastSyncAt = 0L,
 isLocalUser = true,
 isPremium = false
 )

 // Save local user to preferences
 prefs.edit()
 .putString("local_user_id", localUserId)
 .putString("local_user_name", user.displayName)
 .putBoolean("is_local_user", true)
 .apply()

 _currentUser.value = user
 _isSignedIn.value = true

 return user
 }

 private fun getLocalUser(): User? {
 if (!prefs.getBoolean("is_local_user", false)) return null

 val localUserId = prefs.getString("local_user_id", null) ?: return null
 val displayName = prefs.getString("local_user_name", "Local User")

 return User(
 uid = localUserId,
 email = "",
 displayName = displayName,
 photoUrl = null,
 createdAt = System.currentTimeMillis(),
 lastSyncAt = 0L,
 isLocalUser = true,
 isPremium = false
 )
 }

 private fun clearLocalUser() {
 prefs.edit()
 .remove("local_user_id")
 .remove("local_user_name")
 .remove("is_local_user")
 .apply()
 }

 fun getCurrentFirebaseUser(): FirebaseUser? = auth.currentUser

 private fun FirebaseUser.toUser(): User {
 return User(
 uid = uid,
 email = email ?: "",
 displayName = displayName,
 photoUrl = photoUrl?.toString(),
 createdAt = System.currentTimeMillis()
 )
 }
}","language":"kotlin"},"codebaseEnabled":true,"usedRules":["zen-rules://repo/.zencoder/rules/repo.md"]},"createdAt":1756870137128,"isInternal":false,"rawContent":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For now, sign in/sync will be free, but there should be a note during sign in that this feature will possibly be premium in the future"}]}]},"autoAppliedRules":[]}],"isAgent":true,"isNameGenerated":true,"isCustomAgent":false,"isUnitTestsAgent":false,"isE2EAgent":false,"isWebDevAgent":false,"isQnaAgent":false,"isRepoInfoAgent":false,"model":"default"},"13f935ac-ac46-4cde-a546-9f3bc1a14294":{"id":"13f935ac-ac46-4cde-a546-9f3bc1a14294","createdAt":1756872111365,"updatedAt":1756993235694,"title":"For now, sign in/sync will be free, but there s...","messages":[{"id":"c00533de-b9b4-41b7-8897-0a050681da6c","role":"user","content":[{"type":"text","text":"For now, sign in/sync will be free, but there should be a note during sign in that this feature will possibly be premium in the future."},{"type":"text","text":"Ensure app operates normally as before, and only presents the sign in screen when you choose to do so in settings"}],"context":{"currentFile":{"path":"app/src/main/java/com/jumblemint/cows/auth/AuthService.kt","fsPath":"C:/Users/jeepi/AndroidStudioProjects/cows/app/src/main/java/com/jumblemint/cows/auth/AuthService.kt","sources":["opened_tab"],"content":"package com.jumblemint.cows.auth

