+ suspend fun ensureDefaultHerd(repository: com.jumblemint.cows.data.repository.CattleRepository) {
+ val currentUser = _currentUser.value ?: return
+ 
+ // Check if user already has a herd
+ val existingHerds = repository.getHerdsByUser(currentUser.uid)
+ existingHerds.collect { herds ->
+ if (herds.isEmpty()) {
+ // Create default herd
+ val herdId = UUID.randomUUID().toString()
+ val defaultHerd = com.jumblemint.cows.data.model.Herd(
+ id = herdId,
+ name = "${currentUser.displayName}'s Herd",
+ description = "Default herd",
+ ownerId = currentUser.uid,
+ createdAt = System.currentTimeMillis(),
+ updatedAt = System.currentTimeMillis()
+ )
+ 
+ repository.insertHerd(defaultHerd)
+ 
+ // Add user as owner
+ val membership = com.jumblemint.cows.data.model.HerdMember(
+ herdId = herdId,
+ userId = currentUser.uid,
+ role = com.jumblemint.cows.data.model.HerdRole.OWNER,
+ joinedAt = System.currentTimeMillis()
+ )
+ repository.insertHerdMember(membership)
+ }
+ return@collect // Exit after first emission
+ }
+ }
